import hashlib, pathlib

def sha256(p):
    return hashlib.sha256(p.read_bytes()).hexdigest()

def validate(restore_dir, golden, iocs):
    """golden: {relative path: sha256} saved when the system was known good.
    iocs: set of sha256 values of attacker tools from the investigation."""
    report = {"ok": [], "changed": [], "new": [], "malicious": []}
    for p in sorted(pathlib.Path(restore_dir).rglob("*")):
        if not p.is_file():
            continue
        rel, h = str(p.relative_to(restore_dir)), sha256(p)
        if h in iocs:
            report["malicious"].append(rel)       # known attacker file
        elif rel not in golden:
            report["new"].append(rel)             # not in the baseline
        elif golden[rel] != h:
            report["changed"].append(rel)         # differs from baseline
        else:
            report["ok"].append(rel)
    return report
